const searchReader = tool({ type: '@n8n/n8n-nodes-langchain.toolWorkflow', version: 2.2, config: { name: "Search: Reader", parameters: { description: "Search the web only to find a company's official website. Input: the company name. Returns up to 5 results, each with title, url, description and date.", workflowId: { __rl: true, mode: 'id', value: 'bK1o2w8TdT4WUeUL', cachedResultName: 'JML tool: web search (slim)' }, workflowInputs: { mappingMode: 'defineBelow', value: { query: "={{ $fromAI('query', 'Concise web search query', 'string') }}" }, matchingColumns: [], schema: [{ id: 'query', displayName: 'query', required: false, defaultMatch: false, display: true, canBeUsedToMatch: true, type: 'string', removed: false }], attemptToConvertTypes: false, convertFieldsToString: false } } } });

